edits.oldText:
_Cycle('void-settings-screen', 'screen', labelFor(cfg.type), cycleScreen),
if (Platform.isLinux && cfg is CassetteScreenConfig cassetteCfg)
  _Cycle(
    'void-settings-cassette-variant',
    'color scheme',
    cassetteVariantMeta[cassetteCfg.variant]!.label,
    () {
      final next = CassetteVariant.values[
          (cassetteCfg.variant.index + 1) % CassetteVariant.values.length];
      settings.saveScreenConfig(cassetteCfg.copyWith(variant: next));
    },
  ),

